INSERT INTO enterprise_verified_identity (
    verified_identity_id, enterprise_id, user_id, provider,
    provider_subject_digest, identity_digest, issued_at, expires_at, disabled_at
) VALUES (
    #{verifiedIdentityId}, #{enterpriseId}, #{userId}, #{provider},
    #{providerSubjectDigest}, #{identityDigest}, #{issuedAt}, #{expiresAt}, #{disabledAt}
)
ON CONFLICT (verified_identity_id) DO NOTHING

mapper.update:
UPDATE enterprise_verified_identity
SET disabled_at = COALESCE(disabled_at, #{disabledAt})
WHERE verified_identity_id = #{id}

