SELECT *
FROM enterprise_user_permission
WHERE enterprise_id = #{enterpriseId}
  AND user_id = #{userId}
  AND permission = #{permission}

SELECT *
FROM enterprise_user_permission
WHERE enterprise_id = #{enterpriseId}
  AND user_id = #{userId}
  AND enabled = TRUE
ORDER BY permission

SELECT *
FROM enterprise_user_permission
WHERE enterprise_id = #{enterpriseId}
  AND user_id = #{userId}
  AND permission = ANY(
      #{permissions,jdbcType=ARRAY,typeHandler=com.robothree.central.persistence.mybatis.typehandler.PostgresTextArrayTypeHandler}
  )
ORDER BY permission
FOR UPDATE

SELECT *
FROM enterprise_device
WHERE enterprise_id = #{enterpriseId}
  AND device_key_id = #{deviceKeyId}

SELECT *
FROM enterprise_device
WHERE enterprise_id = #{enterpriseId}
  AND public_key_digest = #{publicKeyDigest}

mapper.insert:
INSERT INTO device_enrollment_grant (
    enrollment_grant_id, code_digest, enterprise_id, authorized_user_id,
    issued_at, expires_at, consumed_at, disabled_at
) VALUES (
    #{enrollmentGrantId}, #{codeDigest}, #{enterpriseId}, #{authorizedUserId},
    #{issuedAt}, #{expiresAt}, #{consumedAt}, #{disabledAt}
)
ON CONFLICT (enrollment_grant_id) DO NOTHING

mapper.update:
UPDATE device_enrollment_grant
SET consumed_at = #{consumedAt}
WHERE enrollment_grant_id = #{id}
  AND consumed_at IS NULL

UPDATE device_challenge
SET consumed_at = #{consumedAt},
    consumed_by = #{consumedBy},
    consumed_request_digest = #{requestDigest}
WHERE challenge_id = #{id}
  AND consumed_at IS NULL
